120. /// pre-allocation succeeds, so other code never observes a partially-initialized identity map.
121. pub(crate) fn init(
122.     kernel_pd_paddr: PageDirectoryAddress,
123.     kernel_cr3: Cr3Register,
124. ) -> Result<(), Error> {
125.     // Pre-allocate page tables for all PDE indices in [0, MEMORY_SIZE).
126.     // This covers all physical memory, so no new PDEs are created at runtime.
127.     let pd_paddr: usize = kernel_pd_paddr.into_raw_value();
128.     let pde_count: usize = MEMORY_SIZE / mem::PGTAB_SIZE;
129.     for i in 0..pde_count {
130.         let pde_idx: TableIndex = paging::pd_index(i * mem::PGTAB_SIZE);
131.         // SAFETY: the PD is identity-mapped.
132.         let pd: Table<PageDirectoryEntry> = unsafe { Table::from_address(pd_paddr) };
133.         ensure_pt(pd, pde_idx)?;
134.     }
135. 
136.     // Publish the kernel PD and CR3 only after pre-allocation succeeds, so that other code
137.     // (e.g. `sync_kernel_pdes`, `with_kernel_address_space`) never observes a partially-
138.     // initialized identity map.
139.     KERNEL_PD_PADDR.store(kernel_pd_paddr.into_raw_value(), Ordering::Release);
140.     KERNEL_CR3.store(kernel_cr3.into_u32(), Ordering::Release);
141. 
142.     Ok(())
143. }
144. 
145. ///
146. /// # Description
147. ///
148. /// Copies bytes between two memory regions, after ensuring that both ranges are identity-mapped in
149. /// the kernel address space.
150. ///
151. /// # Parameters
152. ///
153. /// - `dst`: Destination physical address.
154. /// - `src`: Source physical address.
155. /// - `size`: Number of bytes to copy.
156. ///
157. /// # Returns
158. ///
159. /// Upon success, empty is returned. Upon failure, an error is returned instead.
160. ///
161. /// # Errors
162. ///
163. /// - [`ErrorCode::BadAddress`]: One of the physical ranges is invalid or overflows.
164. /// - Any error propagated by the lazy identity mapper while preparing the ranges.
165. ///
166. /// # Notes
167. ///
168. /// If `size == 0`, this function is a no-op and returns success.
169. ///
170. pub(crate) fn memcpy(dst: *mut u8, src: *const u8, size: usize) -> Result<(), Error> {
171.     // Check if copy size is zero.
172.     if size == 0 {
173.         return Ok(());
174.     }
175. 
176.     let dst_start: usize = dst as usize;
177.     let src_start: usize = src as usize;
178.     let dst_end: usize = dst_start.checked_add(size).ok_or_else(|| {
179.         error!("memcpy(): destination range overflows (dst={dst_start:#x}, size={size:#x})");
180.         Error::new(ErrorCode::BadAddress, "memcpy(): destination range overflows")
181.     })?;
182.     let src_end: usize = src_start.checked_add(size).ok_or_else(|| {
183.         error!("memcpy(): source range overflows (src={src_start:#x}, size={size:#x})");
184.         Error::new(ErrorCode::BadAddress, "memcpy(): source range overflows")
185.     })?;
186. 
187.     // Check if copy ranges overlap.
188.     if (dst_start..dst_end).contains(&src_start) || (src_start..src_end).contains(&dst_start) {
189.         error!(
190.             "memcpy(): source and destination ranges overlap (dst={dst_start:#x}, \
191.              src={src_start:#x}, size={size:#x})"
192.         );
193.         return Err(Error::new(
194.             ErrorCode::BadAddress,
195.             "memcpy(): source and destination ranges overlap",
196.         ));
197.     }
198. 
199.     with_kernel_address_space(|| {
200.         let src_addr: PhysicalAddress = PhysicalAddress::from_raw_value(src as usize)?;
201.         let (src_start, src_size) = page_aligned_cover(src_addr, size)?;
202.         ensure_identity_mapped_range(src_start, src_size)?;
203.         let dst_addr: PhysicalAddress = PhysicalAddress::from_raw_value(dst as usize)?;
204.         let (dst_start, dst_size) = page_aligned_cover(dst_addr, size)?;
205.         ensure_identity_mapped_range(dst_start, dst_size)?;
206. 
207.         // SAFETY: both `src` and `dst` are identity-mapped (virtual == physical) and
208.         // valid for `size` bytes. The overlap check above guarantees non-overlapping ranges.
209.         unsafe {
210.             fast_memcpy(dst, src, size);
211.         }
212.         Ok(())
213.     })
214. }
215. 
216. ///
217. /// # Description
218. ///
219. /// Fills bytes in a memory range with a byte value, after ensuring that the full target range is
220. /// identity-mapped in the kernel address space.
221. ///
222. /// # Parameters
223. ///
224. /// - `base`: Starting physical address of the target range.
225. /// - `value`: Byte value to fill.
226. /// - `size`: Number of bytes to fill.
227. ///
228. /// # Returns
229. ///
230. /// Upon success, empty is returned. Upon failure, an error is returned instead.
231. ///
232. /// # Errors
233. ///
234. /// - [`ErrorCode::BadAddress`]: The target range is invalid or overflows.
235. /// - Any error propagated by the lazy identity mapper while preparing the range.
236. ///
237. /// # Notes
238. ///
239. /// If `size == 0`, this function is a no-op and returns success.
240. ///
241. pub(crate) fn memset(base: *mut u8, value: u8, size: usize) -> Result<(), Error> {
242.     // Check if fill size is zero.
243.     if size == 0 {
244.         return Ok(());
245.     }
246. 
247.     let base_start: usize = base as usize;
248.     // Check if fill range overflows.
249.     base_start.checked_add(size).ok_or_else(|| {
250.         error!("memset(): target range overflows (base={base_start:#x}, size={size:#x})");
251.         Error::new(ErrorCode::BadAddress, "memset(): target range overflows")
252.     })?;
253. 
254.     with_kernel_address_space(|| {
255.         let base_addr: PhysicalAddress = PhysicalAddress::from_raw_value(base as usize)?;
256.         let (base_start, base_size) = page_aligned_cover(base_addr, size)?;
257.         ensure_identity_mapped_range(base_start, base_size)?;
258. 
259.         // SAFETY: `base` is identity-mapped (virtual == physical) and valid for
260.         // writes of `size` bytes.
261.         unsafe {
262.             fast_memset(base, value, size);
263.         }
264.         Ok(())
265.     })
266. }
267. 
268. ///
269. /// # Description
270. ///
271. /// Copies all present kernel identity-mapping PDEs from the kernel page directory into a target
272. /// page directory. This covers `[0, MEMORY_SIZE)` and ensures that the target PD (typically a
273. /// new user process PD) can access all kernel identity-mapped memory. Because all PDEs in this
274. /// range are pre-allocated at boot ([`init`]), this is a simple copy of already-present entries.
275. ///
276. /// # Parameters
277. ///
278. /// - `target_pd_paddr`: Physical address of the target page directory.
279. ///
280. /// # Returns
281. ///
282. /// Upon success, `Ok(())`. Upon failure, an error is returned.
283. ///
284. /// # Notes
285. ///
286. /// This function should be called once when constructing a new user address space.
287. ///
288. pub(crate) fn sync_kernel_pdes(target_pd_paddr: PageDirectoryAddress) -> Result<(), Error> {
289.     let kernel_pd_paddr: usize = KERNEL_PD_PADDR.load(Ordering::Acquire);
290.     if kernel_pd_paddr == 0 {
291.         return Ok(());
292.     }
293. 
294.     // SAFETY: the kernel PD is identity-mapped (BSS-backed). The target PD is backed by a
295.     // kernel page whose physical address is identity-mapped in the kernel address space.
296.     let kernel_pd: Table<PageDirectoryEntry> = unsafe { Table::from_address(kernel_pd_paddr) };
297.     let target_pd: Table<PageDirectoryEntry> =
298.         unsafe { Table::from_address(target_pd_paddr.into_raw_value()) };
299. 
300.     // Number of PDEs to sync — bounded by MEMORY_SIZE.
301.     let kernel_pde_count: usize = MEMORY_SIZE / mem::PGTAB_SIZE;
302. 
303.     for i in 0..kernel_pde_count {
304.         // SAFETY: `i` is always < PAGE_TABLE_LENGTH because MEMORY_SIZE < 4 GiB.
305.         let pde_idx: TableIndex = paging::pd_index(i * mem::PGTAB_SIZE);
306. 
307.         let kernel_pde: PageDirectoryEntry = unsafe { kernel_pd.read(pde_idx) }
308.             .ok_or_else(|| Error::new(ErrorCode::InvalidArgument, "invalid PDE index"))?;
309. 
310.         if !kernel_pde.is_present() {
311.             continue;
312.         }
313. 
314.         // Only install the kernel PDE if the target PD does not already have one.
315.         let target_pde: PageDirectoryEntry = unsafe { target_pd.read(pde_idx) }
316.             .ok_or_else(|| Error::new(ErrorCode::InvalidArgument, "invalid PDE index"))?;
317. 
318.         if !target_pde.is_present() {
319.             unsafe { target_pd.write(pde_idx, kernel_pde) };
320.         }

