         let target_pde: PageDirectoryEntry = unsafe { target_pd.read(pde_idx) }
             .ok_or_else(|| Error::new(ErrorCode::InvalidArgument, "invalid PDE index"))?;

         if !target_pde.is_present() {
             unsafe { target_pd.write(pde_idx, kernel_pde) };
